// SPDX-License-Identifier: GPL-3.0-or-later
// End-to-end Meshtastic receive chain on the host, without USB:
//   RTL-SDR-style u8 IQ at 2.4 MS/s (LoRa frame generated by the vendored
//   upstream loratx, +200 kHz off the LO) -> Receiver VFO tap (exact 1 MS/s
//   complex f32) -> registry "meshtastic" backend (embedded lorarx PHY +
//   native MeshtasticParser) -> `message` event JSON.
// Checks the real packet fields, PHY metadata and the tuned frequency, then
// that reset() restarts the PHY cleanly (same packet decoded again) and that
// a second backend instance takes over the process-global PHY.
//
// Usage: sdrcore_meshtastic_phy_test <capture.u8>
#include "../src/dsp/receiver.h"
#include "decoder.hpp"
#include <nlohmann/json.hpp>

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iterator>
#include <memory>
#include <string>
#include <vector>

namespace {
int failures = 0;
void check(bool ok, const char* what) {
  std::printf("%s: %s\n", ok ? "PASS" : "FAIL", what);
  if (!ok) ++failures;
}

std::unique_ptr<sdrcore::decoder::Decoder> make_meshtastic() {
  for (const auto& entry : sdrcore::decoder::registry()) {
    if (entry.descriptor.id == std::string("meshtastic") && entry.create)
      return entry.create();
  }
  return nullptr;
}

const char* kConfig =
    R"({"version":1,"settings":{"preset":"LongFast","region":"EU_868","channels":[]}})";

struct Rig {
  std::unique_ptr<sdrcore::dsp::Receiver> rx = sdrcore::dsp::make_receiver();
  SdrV3Controls c{};
  SdrV3Display d{};
  sdrcore::dsp::ProcessResult result;
  Rig() {
    c.size = sizeof c;
    c.revision = SDR_V3_REVISION;
    c.sample_rate = 2400000;
    c.center_frequency_hz = 869325000;
    c.vfo_offset_hz = 200000;  // tuned 869.525 MHz, EU_868 LongFast slot
    c.bandwidth_hz = 250000;
    c.mode = SDR_V3_NFM;
    c.volume = 1;
    d.size = sizeof d;
    d.revision = SDR_V3_REVISION;
    d.width = 256;
    d.view_bandwidth_hz = c.sample_rate;
    rx->configure(c, d);
  }
  void feed(const std::vector<uint8_t>& iq) {
    for (size_t at = 0; at < iq.size(); at += 48000) {
      const size_t n = std::min<size_t>(48000, iq.size() - at);
      rx->process(iq.data() + at, n, result);
    }
  }
};

std::vector<nlohmann::json> drain(sdrcore::decoder::Decoder& dec) {
  std::vector<nlohmann::json> out;
  sdrcore::decoder::Event ev;
  while (dec.take_event(ev)) {
    if (ev.kind != sdrcore::decoder::Result::message) continue;
    out.push_back(nlohmann::json::parse(ev.payload.begin(), ev.payload.end()));
  }
  return out;
}

bool is_expected_packet(const nlohmann::json& j) {
  return j.value("mode", "") == "Meshtastic" && j.value("src", 0ull) == 3663942836ull &&
         j.value("dst", 0ull) == 4294967295ull && j.value("type", "") == "TEXT_MESSAGE_APP" &&
         j.value("message", "") == "TestingCLU1234" &&
         j.value("freq", 0ull) == 869525000ull;
}
}  // namespace

int main(int argc, char** argv) {
  if (argc != 2) {
    std::fprintf(stderr, "usage: %s <capture.u8>\n", argv[0]);
    return 2;
  }
  std::ifstream in(argv[1], std::ios::binary);
  const std::vector<uint8_t> iq((std::istreambuf_iterator<char>(in)),
                                std::istreambuf_iterator<char>());
  check(iq.size() > 1000000, "capture loaded");

  Rig rig;
  auto dec = make_meshtastic();
  check(dec != nullptr, "registry provides a meshtastic factory");
  if (!dec) return 1;
  check(!dec->configure(R"({"version":1,"settings":{"preset":"LongSlow"}})"),
        "SF12 LongSlow preset is rejected (outside the OpenWebRX+ SF7..11 chain)");
  check(!dec->configure(R"({"version":2,"settings":{}})"), "unknown config version rejected");
  check(dec->configure(kConfig), "LongFast config accepted");
  check(rig.rx->set_decoder(dec.get(), sdrcore::decoder::Input::baseband, 1000000) == 1000000,
        "receiver provides the 1 MS/s complex tap");

  rig.feed(iq);
  auto events = drain(*dec);
  check(events.size() == 1, "exactly one packet decoded from the capture");
  if (!events.empty()) {
    const auto& j = events.front();
    check(is_expected_packet(j), "packet fields: src/dst/type/text/freq");
    const auto& phy = j.value("phy", nlohmann::json::object());
    check(phy.value("crc", 0) == 1, "phy.crc == 1");
    check(phy.value("sf", 0) == 11 && phy.value("cr", 0) == 5, "phy sf 11, cr 4/5");
    check(phy.value("bw", 0.0) == 250.0, "phy.bw is 250 kHz (lorarx Hz converted)");
    check(phy.contains("snr") && phy.contains("level") && phy.contains("nfloor"),
          "phy carries level/snr/noise floor");
    std::printf("event: %s\n", j.dump().c_str());
  }

  // Stream reset restarts lorarx and forgets duplicates: same packet again.
  rig.rx->reset();
  rig.feed(iq);
  events = drain(*dec);
  check(events.size() == 1 && is_expected_packet(events.front()),
        "after reset() the PHY restarts and decodes the packet again");

  // Without reset the duplicate filter drops the repeated packet.
  rig.feed(iq);
  check(drain(*dec).empty(), "duplicate packet dropped without a reset");

  // A second instance takes over the single process-global PHY; the first
  // stays inert and must not crash or emit.
  auto second = make_meshtastic();
  check(second && second->configure(kConfig), "second instance configured");
  rig.feed(iq);
  check(drain(*dec).empty(), "superseded instance emits nothing");
  Rig rig2;
  rig2.rx->set_decoder(second.get(), sdrcore::decoder::Input::baseband, 1000000);
  rig2.feed(iq);
  events = drain(*second);
  check(events.size() == 1 && is_expected_packet(events.front()),
        "new owner decodes the packet");
  rig.rx->set_decoder(nullptr);
  dec.reset();
  rig2.rx->reset();
  rig2.feed(iq);
  events = drain(*second);
  check(events.size() == 1 && is_expected_packet(events.front()),
        "destroying the old instance leaves the owner decoding");

  std::printf("%s (%d failure(s))\n", failures ? "FAILED" : "OK", failures);
  return failures ? 1 : 0;
}
